filter.template:
{%- set ma = integration_entities('magic_areas') -%}
{%- set ex = config.get('exclude', []) -%}
{%- set word = {'motion': 'motion', 'occupancy': 'motion', 'moisture': 'leak', 'door': 'door', 'window': 'window', 'opening': 'opening', 'garage_door': 'garage door', 'smoke': 'smoke', 'gas': 'gas', 'carbon_monoxide': 'CO', 'safety': 'safety', 'tamper': 'tamper', 'vibration': 'vibration'} -%}
{%- set ns = namespace(l=[]) -%}
{%- for s in states.binary_sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','in', word.keys() | list) -%}
{%- if s.entity_id not in ma and s.entity_id not in ex and area_id(s.entity_id) and not is_hidden_entity(s.entity_id) -%}
{%- set ns.l = ns.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': s.entity_id, 'name': area_name(s.entity_id) ~ ' ' ~ word[s.attributes.device_class]}] -%}
{%- endif -%}
{%- endfor -%}
{{ ns.l | sort(attribute='name') }}

{%- set ns = namespace(l=[]) -%}
{%- for p in states.person | sort(attribute='name') -%}
{%- set ns.l = ns.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': p.entity_id, 'name': p.name.split(' ') | first}] -%}
{%- endfor -%}
{{ ns.l }}
